import sys,numpy as np
sys.path.insert(0,'/opt/tools');sys.path.insert(0,'/app/output')
import gen
r=gen.connect();o=r.get_obs(cameras=(gen.CAM_HEAD,),video='both');p=np.asarray(o.meta['proprio']['now'],float)
rows=[];seq=[]
for j in range(7):
 for delta in (.25,0.):
  q=p.copy();q[10+2*j]=p[10+2*j]+delta
  rows.append(gen.act_from_proprio(q,base=(0,0,0),left_grip=[.05,.05],right_grip=[.05,.05]))
  seq.append((j,delta))
a=np.array(rows,dtype=np.float32)
res=r.submit('joint_position',a,dt=.2,interpolate='hold',cameras=(gen.CAM_HEAD,),video='frames',video_fps=30,note='map_left_arm_small_pulses')
res.save('/app/runs/map_left_arm_pulses')
print('seq',seq);print('frames',None if res.proprio is None else res.proprio.shape);print('before',p[35:49]);print('after',res.proprio[-1,35:49]);print('base',res.proprio[-1,28:35]);
if res.proprio is not None:
 for i in range(len(res.proprio)):
  if i%5==0: print(i,np.round(res.proprio[i,35:38],3),np.round(res.proprio[i,42:45],3))
